WITH base AS (SELECT id, order_date, status, amount, discount, shipping_fee, LEAST(amount, discount) AS least_amount_discount, ROUND(amount, 1) AS amount_rounded FROM orders WHERE customer_id IS NOT NULL AND channel IN ('store', 'web')) SELECT status, CASE WHEN amount_rounded >= 71 THEN 'HIGH' ELSE 'LOW' END AS amount_rounded_tier, SIZE(COLLECT_SET(status)) AS num_status, COUNT_IF(status = 'CANCELLED') AS cancelled_events, GROUPING_ID() AS grouping_level FROM base GROUP BY GROUPING SETS ((status, CASE WHEN amount_rounded >= 71 THEN 'HIGH' ELSE 'LOW' END), (status), ());
